import{z as B,x as i,o as E,c as A,q as t,j as l,D as e,d as r,s as p,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Gonzalo–Granger 永久成分","description":"","frontmatter":{"title":"Gonzalo–Granger 永久成分","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gonzalo-granger.md","filePath":"quant/gonzalo-granger.md","lastUpdated":1791063341000}'),h={name:"quant/gonzalo-granger.md"};function d(m,a,C,_,u,c){const n=i("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="gonzalo–granger-永久成分" tabindex="-1">Gonzalo–Granger 永久成分 <a class="header-anchor" href="#gonzalo–granger-永久成分" aria-label="Permalink to &quot;Gonzalo–Granger 永久成分&quot;">​</a></h1><div class="epigraph"><p>协整系统里的价格可以拆成共同的永久趋势与各自的暂时误差。永久成分由对误差修正不反应的线性组合驱动——谁不纠正价差，谁就在定义有效价格。</p><footer>—— Gonzalo and Granger, Estimation of Common Long-Memory Components in Cointegrated Systems, Journal of Business &amp; Economic Statistics, 1995</footer></div><p><a href="/quant/hasbrouck-var">Hasbrouck VAR</a>在单一市场上把成交新息的长期乘数叫做信息含量。缺口是：多条价格已经协整时，永久趋势本身怎么从水平变量里构造出来？Gonzalo 与 Granger（1995）给出共同长期记忆成分（PT 分解）：永久部分是对误差修正项权重为零的组合。主干<a href="/quant/hasbrouck-is">信息份额</a>已经把 PT 与 IS 对照过；本课把 PT 写清，并说明它回答的是「谁跟随谁」，不是「谁贡献了随机游走方差」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个市场交易同一索取权，\\(p_t=(p_{1t},p_{2t})&#39;\\) 协整，\\(\\beta&#39;p_t\\) 平稳。每个价格 = 共同有效价格 + 暂时偏差。有效价格要可估计，必须指定分解。Hasbrouck 信息份额用新息对随机游走<strong>方差</strong>的贡献；那依赖新息相关时的变量顺序。Gonzalo–Granger 问另一句：误差修正系数向量 \\(\\alpha\\) 的正交补 \\(\\alpha_\\perp\\) 所定义的组合 \\(\\alpha_\\perp&#39; p_t\\)，是否就是共同趋势。这个组合对价差不反应——它走出价差，别人来纠正。</p><p>若只做 Hasbrouck 单市场 VAR，没有第二条价格，就谈不上 \\(\\alpha_\\perp\\)。本课默认已经有协整的价格向量：跨市场报价、现货与期货、或成交价与报价中点。</p><p><span class="marginnote">「协整」可以翻译成「两条各自会漂的绳子被拴在一起」：每条价格单独看都走得没边（单位根），但两者的差却被拉在一个固定范围里。正因如此，才能谈「谁偏离、谁去拉回来」。</span></p><h3 id="pt-与-is-不是-rival-的同一数字" tabindex="-1">PT 与 IS 不是 rival 的同一数字 <a class="header-anchor" href="#pt-与-is-不是-rival-的同一数字" aria-label="Permalink to &quot;PT 与 IS 不是 rival 的同一数字&quot;">​</a></h3><p>Baillie、Booth、Tse、Zabotina 以及 Harris、McInish、Wood 的讨论表明：IS 依赖新息相关的正交化，PT 权重不依赖那一层。两者可以给出不同排序：一个市场噪声大但先动，IS 高、PT 权重低。不要把 PT 权重叫做信息份额，也不要在论文里只报一个。</p><p><span class="marginnote">Hasbrouck（1995）自己讨论了与永久–暂时分解的关系。本课补 GG 的构造，避免在信息份额课里把两套代数搅在一起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VECM：</p> \\[\\Delta p_t = \\alpha \\beta&#39; p_{t-1} + \\sum \\Gamma_i \\Delta p_{t-i} + \\varepsilon_t. \\]<p>\\(\\alpha\\) 是误差修正速度。Gonzalo–Granger 永久成分为 \\(f_t=\\alpha_\\perp&#39; p_t\\)（正规化后），暂时成分为与 \\(\\beta\\) 方向相关的平稳部分。\\(\\alpha_\\perp\\) 的经济含义：对价差调整最不敏感的市场，在永久成分里权重大——它「不跟随」，别人跟随它。</p><p>估计：Johansen 得到 \\((\\hat\\alpha,\\hat\\beta)\\)，再算 \\(\\hat\\alpha_\\perp\\)。推断要考虑协整秩与滞后。两个市场时，PT 权重是标量对，和为正规化常数。</p><h3 id="从成交-报价-var-到水平协整" tabindex="-1">从成交-报价 VAR 到水平协整 <a class="header-anchor" href="#从成交-报价-var-到水平协整" aria-label="Permalink to &quot;从成交-报价 VAR 到水平协整&quot;">​</a></h3><p>Hasbrouck（1991）多用差分后的 \\(r_t\\) 与 \\(q_t\\)，不估计共同趋势水平。若把中点与成交价都当 \\(I(1)\\) 水平放入 VECM，PT 可以问：成交价是否比报价更「永久」。这与单市场信息含量互补：一个看交易新息的长期乘数，一个看哪条价格序列在定义趋势。</p>',17)),(E(),l(s,null,{default:e(()=>[p(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8D%8F%E6%95%B4%E4%BB%B7%E6%A0%BC%E5%90%91%E9%87%8F%20p%22%5D%20--%3E%20VECM%5B%22VECM%3A%20%CE%B1%20%E7%BA%A0%E6%AD%A3%20%CE%B2'p%22%5D%0A%20%20VECM%20--%3E%20PT%5B%22%E6%B0%B8%E4%B9%85%3A%20%CE%B1%E2%8A%A5'p%20%E4%B8%8D%E7%BA%A0%E6%AD%A3%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20VECM%20--%3E%20TR%5B%22%E6%9A%82%E6%97%B6%3A%20%E5%9B%B4%E7%BB%95%E8%B6%8B%E5%8A%BF%E7%9A%84%E5%B9%B3%E7%A8%B3%E5%81%8F%E5%B7%AE%22%5D%0A%20%20VECM%20-.-%3E%7C%22%E5%8F%A6%E4%B8%80%E5%88%86%E8%A7%A3%22%7C%20IS%5B%22IS%3A%20%E6%96%B0%E6%81%AF%E5%AF%B9%E6%B8%B8%E8%B5%B0%E6%96%B9%E5%B7%AE%E7%9A%84%E8%B4%A1%E7%8C%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[r("误差修正是「谁去消除套利」。若市场 1 的报价几乎不因价差而改，市场 2 频繁把价差拉回去，则市场 1 定义趋势。这在经济上像价格发现的领导权，但领导权是对"),o("strong",null,"水平调整"),r("而言，不是对方差贡献而言。噪声很大的领导市场仍可能在 IS 上被稀释，因为随机游走新息的方差分解把相关噪声算进去。")],-1)),(E(),l(s,null,{default:e(()=>[p(n,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%BB%B7%E5%B7%AE%20%CE%B2'p%20%E5%81%8F%E7%A6%BB%22%5D%20--%3E%20M1%7B%22%E5%B8%82%E5%9C%BA%201%20%E8%B0%83%E6%95%B4%E6%8A%A5%E4%BB%B7%E5%90%97%EF%BC%9F%22%7D%0A%20%20S%20--%3E%20M2%7B%22%E5%B8%82%E5%9C%BA%202%20%E8%B0%83%E6%95%B4%E6%8A%A5%E4%BB%B7%E5%90%97%EF%BC%9F%22%7D%0A%20%20M1%20--%3E%7C%22%E5%87%A0%E4%B9%8E%E4%B8%8D%E8%B0%83%22%7C%20LEAD%5B%22%CE%B1%20%E7%AC%AC%201%20%E8%A1%8C%20%E2%89%88%200%EF%BC%9A%E5%B8%82%E5%9C%BA%201%20%E4%B8%8D%E7%BA%A0%E6%AD%A3%22%5D%0A%20%20M2%20--%3E%7C%22%E9%A2%91%E7%B9%81%E6%8B%89%E5%9B%9E%22%7C%20FOLLOW%5B%22%CE%B1%20%E7%AC%AC%202%20%E8%A1%8C%E5%A4%A7%EF%BC%9A%E5%B8%82%E5%9C%BA%202%20%E8%B7%9F%E9%9A%8F%22%5D%0A%20%20LEAD%20--%3E%20PT%5B%22%CE%B1%E2%8A%A5'p%20%E6%9D%83%E9%87%8D%E5%81%8F%E5%90%91%E5%B8%82%E5%9C%BA%201%22%5D%0A%20%20FOLLOW%20--%3E%20PT%0A%20%20PT%20--%3E%20CONC%5B%22%E5%85%B1%E5%90%8C%E8%B6%8B%E5%8A%BF%E7%94%B1%E5%B8%82%E5%9C%BA%201%20%E5%AE%9A%E4%B9%89%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">用数字感受一下 \\(\\alpha_\\perp\\)：两个市场时若 \\(\\alpha=(0,\\,-0.8)&#39;\\)，即只有市场 2 以每次 0.8 的速度把价差拉回，那么「不纠正价差」的方向就是市场 1 自己——共同趋势几乎全由市场 1 的价格构成。市场 2 动得越勤，它在永久成分里反而越没份量。</span></p><p>与 Grossman–Miller 对照：暂时成分可以是库存压力；PT 把它从共同趋势里拿掉，但不命名。与 Kyle 对照：共同趋势才是被写入的 \\(V\\) 的代理，暂时成分不是知情交易的目标。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>协整秩、线性、常 \\(\\alpha\\)，在结构断裂（切换主导市场、涨跌停）时失效。高频噪声使水平变量的单位根检验脆弱，许多应用改在一秒或更粗采样上做。PT 权重不是交易策略信号：跟随「永久成分」仍可能付价差与滑点。三个以上市场时 \\(\\alpha_\\perp\\) 的基底不唯一，正规化必须事先说清。</p><p><span class="marginnote">不要用 PT 权重去给交易所排名做广告。样本时段、是否用中点还是成交、是否含零股，都会改 \\(\\alpha\\)。</span></p><p><span class="marginnote">初学者容易把「PT 权重高」当成「这个市场质量好」。实际上权重高的市场往往只是<strong>反应慢</strong>：它不急着纠正价差，于是统计上成了趋势的定义者。领导权是描述，不是褒奖。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Gonzalo–Granger 用 \\(\\alpha_\\perp&#39;p\\) 构造协整系统的共同永久成分：不纠正价差的组合定义趋势。</li><li>信息份额分解的是随机游走新息方差；PT 分解的是水平调整的领导权。两者可排序不同。</li><li>单市场成交–报价 VAR 的永久乘数与跨市场 PT 是不同问题。</li><li>出处：Gonzalo and Granger, <em>Journal of Business &amp; Economic Statistics</em>, 1995；对照 Hasbrouck, <em>Journal of Finance</em>, 1995。</li></ul>',8))])}const P=B(h,[["render",d]]);export{T as __pageData,P as default};
